body {
   height: 100%;
   width: 100%;
   margin: 0;
   padding: 0;
   overflow: hidden;

   font-family: "Segoe UI", sans-serif;
}

/* This is an <img> rather than using background-image because IE8
 * does not support background-size. */
#background {
  min-height: 100%;
  min-width: 100%;

  width: 100%;
  height: auto;

  position: fixed;
  top: 0;
  left: 0;

  z-index: -1;
}

body.high-contrast #background {
  display: none;
}

.no-focus-outline {
  outline: none;
}

